def _load_packet():
    s = PACKET_JSON
    a = s.find(SENTINEL) + len(SENTINEL)
    b = s.rfind(SENTINEL)
    raw = s[a:b].strip()
    return json.loads(raw)


_PACKET = _load_packet()
FILES = _PACKET["files"]
MANIFEST = _PACKET["manifest"]
META = _PACKET.get("meta") or {}


def src(path: str) -> str:
    if path not in FILES:
        raise AssertionError("packet missing %s" % path)
    return FILES[path]


def list_files():
    print("%d embedded source files  generated=%s  commit=%s" % (
        len(MANIFEST), META.get("generated"), META.get("pinned_commit")))
    for m in MANIFEST:
        print("  %7d  %5d  %s  %s" % (m["bytes"], m["lines"], m["sha256"], m["path"]))


def extract(dest="trading_app_src"):
    destp = Path(dest)
    destp.mkdir(parents=True, exist_ok=True)
    for path, content in FILES.items():
        p = destp / path
        p.parent.mkdir(parents=True, exist_ok=True)
        data = content.encode("utf-8")
        p.write_bytes(data)
        expect = next(x["sha256"] for x in MANIFEST if x["path"] == path)
        got = hashlib.sha256(data).hexdigest()
        if got != expect:
            raise SystemExit("EXTRACT HASH MISMATCH %s\n  expect %s\n  got    %s" % (path, expect, got))
        print("wrote %s  %d bytes  %s" % (p, len(data), got))
    print("extracted %d files into %s" % (len(FILES), destp.resolve()))


def _exec_embedded(path: str) -> dict:
    ns = {"__name__": "embedded_" + path.replace("/", "_").replace(".", "_"), "__file__": path}
    exec(compile(src(path), path, "exec"), ns)
    return ns


class PacketIntegrity(unittest.TestCase):
    def test_manifest_hashes_match_embedded_bytes(self):
        self.assertGreater(len(MANIFEST), 40)
        for m in MANIFEST:
            data = src(m["path"]).encode("utf-8")
            self.assertEqual(len(data), m["bytes"], m["path"])
            self.assertEqual(hashlib.sha256(data).hexdigest(), m["sha256"], m["path"])

    def test_required_paths_present(self):
        required = [
            "src/kernel/index.ts",
            "src/desk/writer.ts",
            "src/desk/commands.ts",
            "src/desk/verify-freeze.ts",
            "src/desk/learn.ts",
            "src/desk/learn-policy.ts",
            "src/desk/bootstrap.ts",
            "src/desk/queries.ts",
            "src/desk/alpaca.ts",
            "migrations/0002_trading_app.sql",
            "migrations/0008_proposal_only.sql",
            "TRADING_APP_STANDALONE.py",
            "TRADING_APP_LEARN_PROPOSAL_ONLY.py",
            "trading_app_kernel_audit.py",
        ]
        missing = [p for p in required if p not in FILES]
        self.assertEqual(missing, [])

    def test_live_workspace_matches_packet_when_present(self):
        here = Path(__file__).resolve().parent
        if not (here / "src" / "kernel" / "index.ts").is_file():
            self.skipTest("live repo not next to this packet")
        mismatches = []
        missing_live = []
        for m in MANIFEST:
            live = here / m["path"]
            if not live.is_file():
                missing_live.append(m["path"])
                continue
            got = hashlib.sha256(live.read_bytes()).hexdigest()
            if got != m["sha256"]:
                mismatches.append(m["path"])
        self.assertEqual(mismatches, [], "packet stale vs live workspace")
        # Probe files and src must exist live; skip-only for optional docs is not allowed here.
        self.assertEqual(missing_live, [])


class SourceLock(unittest.TestCase):
    def test_kernel_domain_and_no_vicia_engine(self):
        k = src("src/kernel/index.ts")
        self.assertIn("Trading App|input|2", k)
        self.assertIn("CANONICAL_NUMBERS_MUST_BE_STRINGS", k)
