def _load_probe_classes():
    kernel = _exec_embedded("trading_app_kernel_audit.py")
    freeze = _exec_embedded("TRADING_APP_STANDALONE.py")
    learn = _exec_embedded("TRADING_APP_LEARN_PROPOSAL_ONLY.py")
    classes = []
    for ns, names in (
        (kernel, ("Golden", "Adversarial", "PatchRegression")),
        (freeze, ("VerifierProbes",)),
        (learn, ("ProposalOnlyProbes",)),
    ):
        for name in names:
            if name not in ns:
                raise SystemExit("embedded %s missing class %s" % (ns.get("__file__"), name))
            classes.append(ns[name])
    return classes, kernel, freeze, learn


BRIEF = """
================================================================
SCRUTINY BRIEF — entire app packet
================================================================
Pinned: {pinned}
H01:    {h01}
Fill:   modeledFill("123.456789") == {fill}

This packet embeds the production TypeScript desk plus three runnable
authorities:

  trading_app_kernel_audit.py     kernel goldens + adversarial + patches
  TRADING_APP_STANDALONE.py       freeze verifier + H01 + modeled fill
  TRADING_APP_LEARN_PROPOSAL_ONLY.py  proposal-only learner

TypeScript the reviewer must still attack after probes pass:
  src/kernel/index.ts
  src/desk/writer.ts
  src/desk/commands.ts
  src/desk/verify-freeze.ts
  src/desk/learn.ts
  src/desk/learn-policy.ts
  src/desk/bootstrap.ts
  src/desk/queries.ts
  src/desk/alpaca.ts
  migrations/0002_trading_app.sql
  migrations/0008_proposal_only.sql

Required answers:
  1. Two different sealed cards, same PRODUCTION input hash? Same under the paste?
  2. ROUND_HALF_UP tie: Python Decimal vs BigInt port — counterexample if they diverge.
  3. direction_hit(entry, exit) with exit==entry — MISS?
  4. implied_move as float 0.08 — PREDICT? Production says no.
  5. IMPAIRED_EXIT occupying a slot — new PREDICT same day denied?
  6. BYTE_VERIFIED after corrupting sealed_input.card but leaving snapshot_hash?
  7. chooseRevision ever adopted=true? maybeReviseRule ever REGISTER_RULE?
  8. bootstrap calling reviseClosedManifests?
  9. Operator results payload leaking hit_rate / P&L?
 10. LIVE host reachable? Wrap key created in /tmp?

Honesty bar: do not invent passing tests. Name the bug or the residual risk.
""".format(pinned=PINNED, h01=H01, fill=GOLDEN_FILL)


def run_probes() -> int:
    print("Trading App entire-app packet")
    print("GitHub: https://github.com/vicia05-lab/trading-app")
    print("Pinned: %s" % PINNED)
    print("Embedded files: %d" % len(MANIFEST))
    print()
    probe_classes, kernel, freeze, learn = _load_probe_classes()
    loader = unittest.TestLoader()
    suite = unittest.TestSuite()
    suite.addTests(loader.loadTestsFromTestCase(PacketIntegrity))
    suite.addTests(loader.loadTestsFromTestCase(SourceLock))
    for cls in probe_classes:
        suite.addTests(loader.loadTestsFromTestCase(cls))
    result = unittest.TextTestRunner(verbosity=2).run(suite)
    print()
    print(BRIEF)
    fill = freeze.get("modeled_fill", lambda *_a, **_k: None)("123.456789")
    h = freeze.get("input_hash")
    if callable(h):
        got_h = h(
            "manifest-20260914", "SEC-A",
            "1" * 64, "2" * 64, "3" * 64, "4" * 64, "5" * 64, 3,
            [("obs-z", "a" * 64), ("obs-a", "b" * 64)],
        )
        print("Cross-check H01 from embedded standalone:", got_h)
        if got_h != H01:
            print("RESULT: FAIL — embedded standalone H01 drifted.")
            return 1
    print("Cross-check modeled fill from embedded standalone:", fill)
    if fill != GOLDEN_FILL:
        print("RESULT: FAIL — embedded standalone fill drifted.")
        return 1
    if not result.wasSuccessful():
        print("RESULT: FAIL — packet, kernel, verifier, learner, or lock is wrong.")
        return 1
    print("RESULT: entire-app probes passed.")
    print("Reviewer: extract the TypeScript desk and try to break the port.")
    print("  python3 TRADING_APP_ENTIRE_APP.py --extract")
    print("Then attack it. Do not rubber-stamp.")
    return 0


def main(argv=None) -> int:
    argv = list(sys.argv[1:] if argv is None else argv)
    if "--list" in argv:
        list_files()
        return 0
    if "--extract" in argv:
        dest = "trading_app_src"
        if "--dest" in argv:
            dest = argv[argv.index("--dest") + 1]
        extract(dest)
        return 0
    return run_probes()


if __name__ == "__main__":
    raise SystemExit(main())
